function renderPreflight(pf){const box=id('qbPreflight');if(!box)return;const total=Number(pf?.jobs_total||0),ready=Number(pf?.jobs_ready||0);box.innerHTML=`<div class="section-head compact"><b>${tr('Preflight')} · ${ready}/${total} ${tr('Jobs ready')}</b><span class="status-pill">${pf?.ready?tr('READY'):tr('BLOCKED')}</span></div>${(pf?.checks||[]).map(c=>`<div class="validation-line ${c.ok?'ok':'missing'}"><b>${c.ok?'✓':'✕'} ${E(c.label)}</b><small>${E(c.detail||'')}</small></div>`).join('')}${(pf?.blocked_jobs||[]).length?`<details><summary>${tr('Blocked jobs')} · ${pf.blocked_jobs.length}</summary><div>${pf.blocked_jobs.slice(0,12).map(x=>`<p class="qs-warning" data-no-i18n>${E(x.label||x.job_id)} · ${E(x.reason)}</p>`).join('')}</div></details>`:''}`;id('qbLaunch').disabled=!pf?.ready;}
async function refreshPlanPreflight(){if(!plan?.id)return;const d=await req('/benchmarks/'+plan.id+'/preflight');plan.preflight=d.preflight;renderPreflight(plan.preflight);id('qbStatus').textContent=plan.preflight.ready?tr('Preflight passed. The batch is ready to queue.'):tr('Preflight blocked. Configure or verify the required runtime before queueing.');}
async function makePlan(){if(!S.project)throw Error(tr('Open a project first.'));const mode=id('qbMode').value;const direct=mode!=='compare';
 const d={name:id('qbName').value,mode,suite:mode,project_id:S.project.id,prompt:id('qbPrompt').value,params:benchmarkParams(),profile_ids:direct?[id('qbBaseline').value]:checked('qbProfiles'),repeats:Number(id('qbRepeats').value),transformers:checked('qbTransformers'),encoders:checked('qbEncoders'),vaes:checked('qbVaes'),fixed_transformer:id('qbFixedTransformer').value||'@baseline',fixed_encoder:id('qbFixedEncoder').value||'@baseline',fixed_vae:id('qbFixedVae').value||'@baseline',latent_id:id('qbLatent').value,input_artifact_id:id('qbImage').value,cycles:checked('qbCycles').map(Number),use_profile_loras:id('qbUseLoras').checked,lora_ids:checkedLoraIds(),lora_strengths:Object.fromEntries([...id('qbLoras').querySelectorAll('[data-qb-lora-row]')].filter(row=>row.querySelector('input[type=checkbox]').checked).map(row=>[row.dataset.qbLoraRow,Number(row.querySelector('input[type=number]').value)])),lora_combinations:id('qbLoraCombos').value,lock_vae:id('qbLockVae').checked,lock_scheduler:id('qbLockScheduler').checked,auto_strategy:id('qbAutoStrategy').value,prompts:checked('qbAutoPrompts').map(k=>QB_AUTO_PROMPTS.find(x=>x.id===k)).filter(Boolean),load_options:(mode==='auto'&&id('qbQuantizedMode').value)?{quantized_loading:id('qbQuantizedMode').value}:{}};
 if(!d.profile_ids.length)throw Error(tr('Choose at least one model preset.'));if(['auto','transformer','matrix'].includes(mode)&&!d.transformers.length)throw Error(tr('Choose at least one transformer.'));if(['auto','encoder','matrix'].includes(mode)&&!d.encoders.length)throw Error(tr('Choose at least one encoder.'));if(['auto','decode','roundtrip'].includes(mode)&&!d.vaes.length)throw Error(tr('Choose at least one VAE.'));if(mode==='auto'&&!d.prompts.length)throw Error(tr('Choose at least one benchmark prompt.'));
 const r=await req('/benchmarks/plan','POST',d);plan=r.plan;report=null;id('qbPlan').hidden=false;id('qbLaunch').hidden=false;
 const firstParams=plan.entries?.[0]?.params||{};
 const planCfg=firstParams.cfg_enabled?('CFG '+(firstParams.cfg??1)):('CFG OFF');
 const planNegative=firstParams.cfg_enabled&&String(firstParams.negative_prompt||'').trim()?'Negative ON':'Negative OFF';
 const planOOM=firstParams.oom_cpu_decode_fallback?'CPU decode OOM fallback ON':'CPU decode OOM fallback OFF';
 id('qbPlanInfo').textContent=tr('Review before queueing')+' · '+plan.count+' '+tr('Jobs')+' · '+tr('Seed')+' '+plan.seed+' · '+planCfg+' · '+planNegative+' · '+planOOM;
 renderPreflight(plan.preflight||{jobs_total:plan.count,jobs_ready:plan.count,ready:true,checks:[]});
 const skippedPlan=plan.skipped_incompatible_combinations||[];
 id('qbPlanRows').innerHTML=(skippedPlan.length?`<details><summary>${tr('Incompatible combinations skipped')} · ${skippedPlan.length}</summary>${skippedPlan.map(x=>`<p class="qs-warning" data-no-i18n>${E(x.label)} · ${E(x.reason)}</p>`).join('')}</details>`:'')+plan.entries.map((e,i)=>`<div class="qs-plan-row"><b>${i+1}</b><span data-no-i18n>${E(e.label)}</span><span>${E(e.params.width||'')}×${E(e.params.height||'')} · ${E(e.params.steps??0)} ${tr('Steps')}</span></div>`).join('');
 id('qbStatus').textContent=plan.preflight?.ready?tr('Preflight passed. The plan is saved and nothing is running yet.'):tr('Preflight blocked. Fix the reported runtime requirements before queueing.');await history();id('qbHistory').value=plan.id;
}
const seconds=n=>typeof n==='number'?n.toFixed(2)+' s':'—';const memory=n=>typeof n==='number'?(n/1073741824).toFixed(2)+' GiB':'—';
function captureBenchmarkView(){const box=id('qbResultsRows');return {y:window.scrollY,open:box?[...box.querySelectorAll('details')].map((d,i)=>d.open?i:-1).filter(i=>i>=0):[]};}
function restoreBenchmarkView(v){if(!v)return;const box=id('qbResultsRows');if(box){const wanted=new Set(v.open);[...box.querySelectorAll('details')].forEach((d,i)=>d.open=wanted.has(i));}requestAnimationFrame(()=>window.scrollTo({top:v.y,left:0,behavior:'instant'}));}
async function refreshReport(preserveView=true){const rid=report?.id||plan?.id||id('qbHistory').value;if(!rid)return;const view=preserveView?captureBenchmarkView():null;const pid=S.project?.id;const r=await req('/benchmarks/'+rid);if(S.project?.id!==pid||(report?.id||plan?.id||id('qbHistory').value)!==rid)return;report=r.report;
 id('qbResults').hidden=false;id('qbResultsTitle').textContent=report.name;id('qbExport').href=base+'/benchmarks/'+rid+'/export';id('qbCsv').href=base+'/benchmarks/'+rid+'/csv';
 const entries=report.entries;const active=entries.some(x=>['running','queued','cancelling'].includes(x.raw_status||x.status));id('qbCancel').disabled=!active;
 const retryable=entries.filter(x=>['failed','interrupted','planned'].includes(x.raw_status||x.status));id('qbRetry').disabled=!retryable.length;
 const skipped=(report.skipped_incompatible_combinations||[]);id('qbRetryInfo').textContent=retryable.length?retryable.length+' '+tr('failed / missing jobs can be resumed'):'';
 id('qbResultsRows').innerHTML=(skipped.length?`<details class="qs-result"><summary>${E(tr('Incompatible combinations skipped'))} · ${skipped.length}</summary>${skipped.map(x=>`<p class="qs-warning" data-no-i18n>${E(x.label)} · ${E(x.reason)}</p>`).join('')}</details>`:'')+entries.map(e=>`<article class="qs-result"><div class="qs-card-head"><h4 data-no-i18n>${E(e.label)}</h4><span class="status-pill">${E(tr(e.status))}</span></div>${e.url?`<a href="${E(e.url)}" target="_blank" rel="noopener"><img src="${E(e.url)}" alt="${E(e.label)}" loading="lazy"/></a>`:`<div class="qs-placeholder">${Math.round((e.progress||0)*100)}%</div>`}<dl><dt>${tr('Backend')}</dt><dd>${E(e.result?.execution_backend||e.result?.pipeline||'Image Lab worker')}</dd><dt>${tr('Total time')}</dt><dd>${seconds(e.duration_seconds)}</dd><dt>${tr('Sampling + conditioning')}</dt><dd>${seconds(e.result?.conditioning_and_sampling_seconds)}</dd><dt>${tr('Load / decode')}</dt><dd>${seconds(e.result?.load_seconds)} / ${seconds(e.result?.decode_seconds)}</dd><dt>${tr('VRAM allocated / reserved')}</dt><dd>${e.metrics?.peak_gpu_process_bytes?memory(e.metrics.peak_gpu_process_bytes):(memory(e.metrics?.peak_cuda_allocated_bytes)+' / '+memory(e.metrics?.peak_cuda_reserved_bytes))}</dd><dt>${tr('Peak process RAM')}</dt><dd>${memory(e.metrics?.peak_rss_bytes)}</dd></dl>${e.result?.benchmark_vae_backend==='comfyui_hybrid'?`<p class="qs-native">${tr('Baseline sampling + ComfyUI VAE decode.')}</p>`:''}${e.precision_policy==='native_comfyui'?`<p class="qs-native">${tr('Native ComfyUI quantized execution.')}</p>`:''}${e.precision_policy==='reference_dequantize'?`<p class="qs-warning">${tr('Float reconstruction, not native INT8.')}</p>`:''}${e.compatibility_reason?`<p class="qs-warning" data-no-i18n>${E(e.compatibility_reason)}</p>`:''}${e.error?`<details><summary>${tr('Technical error')}</summary><pre>${E(e.error)}</pre></details>`:''}${e.result?.roundtrip?`<details><summary>${tr('Round-trip metrics')}</summary><pre>${E(JSON.stringify(e.result.roundtrip,null,2))}</pre></details>`:''}</article>`).join('');
 restoreBenchmarkView(view);return active;
}
