id('quickPresetSave').onclick=()=>{showView('user-presets');id('qsSaveKind').value='generation';id('qsSaveName').focus();};
try{const v=JSON.parse(sessionStorage.getItem('qwen21_studio_v1')||'null');if(v&&typeof v==='object'&&v.model_preset_id)setup={...setup,...v};}catch(_){}
id('qsModel').onchange=()=>{resetSetup(id('qsModel').value);id('qsFull').value='';};
id('qsGeneration').onchange=()=>{const p=rows('generation').find(x=>x.id===id('qsGeneration').value);if(p)applyGeneration(p);};
id('qsFull').onchange=()=>{const p=rows('full').find(x=>x.id===id('qsFull').value);if(p)apply(p);};
for(const [key]of fields){id('qsOverride-'+key).onchange=()=>{if(id('qsOverride-'+key).checked)setup.overrides[key]=id('qsComponent-'+key).value;else delete setup.overrides[key];id('qsComponent-'+key).disabled=!id('qsOverride-'+key).checked;persist();summary();};id('qsComponent-'+key).onchange=()=>{setup.overrides[key]=id('qsComponent-'+key).value;persist();summary();};}
for(const [key]of options)id('qsOption-'+key).onchange=()=>{const v=id('qsOption-'+key).value;if(v)setup.load_options[key]=v;else delete setup.load_options[key];persist();summary();};
id('qsProfileLoras').onchange=()=>{setup.use_profile_loras=id('qsProfileLoras').checked;persist();};id('qsReset').onclick=()=>resetSetup(setup.model_preset_id);
id('qsRefresh').onclick=e=>act(e.currentTarget,refresh);id('qsSearch').oninput=renderCards;
id('qsSave').onclick=e=>act(e.currentTarget,()=>saveCurrent(false));id('qsReplace').onclick=e=>act(e.currentTarget,async()=>{if(confirm(tr('Replace this user preset?')))await saveCurrent(true);});
id('qsImport').onchange=e=>act(null,async()=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>100000)throw Error('Maximum preset size: 100 kB.');importPayload=JSON.parse(await f.text());id('qsBindings').replaceChildren();id('qsImportPanel').hidden=false;await importCheck();});
id('qsImportPreview').onclick=e=>act(e.currentTarget,()=>importCheck());id('qsImportCommit').onclick=e=>act(e.currentTarget,()=>importCheck(true));id('qsImportCancel').onclick=()=>{id('qsImportPanel').hidden=true;importPayload=null};
id('qsPresetPanel').addEventListener('click',e=>{const tab=e.target.closest('[data-qs-kind]');if(tab){kind=tab.dataset.qsKind;renderCards();return}const b=e.target.closest('[data-qs-do]');if(!b)return;const p=data.presets.find(x=>x.id===b.dataset.id&&x.kind===b.dataset.kind);if(!p)return;act(b,async()=>{const a=b.dataset.qsDo;if(a==='apply'||a==='edit'){apply(p,a==='edit');return}if(a==='delete'){if(confirm(tr('Delete this preset? Model files and images are kept.')))await req('/presets/'+p.kind+'/'+p.id,'DELETE',{});}if(a==='duplicate')await req('/presets/'+p.kind+'/'+encodeURIComponent(p.id)+'/duplicate','POST',{});if(a==='rename'){const name=prompt(tr('Preset name'),p.name);if(name?.trim())await req('/presets','POST',{...p,name:name.trim()});}await refresh();await refreshPresets();});});
id('view-image').addEventListener('input',summary);id('view-image').addEventListener('change',summary);
id('qbMode').onchange=()=>{suiteDefaults();plan=null;id('qbPlan').hidden=true;};id('qbSuggested').onclick=()=>suiteDefaults();id('qbPrepare').onclick=e=>act(e.currentTarget,makePlan);id('qbAutoAll').onclick=()=>{for(const k of ['qbTransformers','qbEncoders','qbVaes','qbAutoPrompts'])setChecks(k,true);};id('qbAutoClear').onclick=()=>{for(const k of ['qbTransformers','qbEncoders','qbVaes','qbAutoPrompts'])setChecks(k,false);};
id('qbSceneNew').onclick=()=>editScene();
id('qbSceneCancel').onclick=closeSceneEditor;
id('qbSceneSave').onclick=e=>act(e.currentTarget,saveScene);
id('qbAutoPrompts').addEventListener('click',e=>{
 const button=e.target.closest('[data-qb-scene-action]');if(!button)return;
 const rid=button.dataset.sceneId,action=button.dataset.qbSceneAction;
 if(action==='edit'){editScene(rid);return;}
 act(button,async()=>{
  if(action==='delete'&&!confirm(tr('Delete this saved scene? Existing benchmark plans will not be changed.')))return;
  if(action==='restore'&&!confirm(tr('Restore the original built-in scene? Existing benchmark plans will not be changed.')))return;
  await req('/benchmark-scenes/'+encodeURIComponent(rid),'DELETE');
  if(sceneEditing===rid)closeSceneEditor();
  await reloadSceneCatalogue();
  id('qbSceneStatus').textContent=tr(action==='restore'?'Original scene restored.':'Saved scene deleted.');
 });
});


document.addEventListener('click',e=>{const b=e.target.closest('[data-qb-check]');if(!b)return;setChecks(b.dataset.qbCheck,b.dataset.value==='1');});
for(const key of ['qbTransformers','qbEncoders','qbVaes','qbProfiles','qbCycles','qbAutoPrompts','qbLoras','qbLoraCombos'])id(key)?.addEventListener('change',estimateBenchmark);id('qbAutoStrategy')?.addEventListener('change',estimateBenchmark);
for(const key of ['qbRepeats','qbWidth','qbHeight','qbSteps','qbSeed','qbCfg'])id(key)?.addEventListener('change',()=>{cfgBenchmarkState();estimateBenchmark()});id('qbCfgEnabled').onchange=()=>{cfgBenchmarkState();estimateBenchmark()};id('qbNegative').oninput=cfgBenchmarkState;
id('qbPreflightRefresh').onclick=e=>act(e.currentTarget,refreshPlanPreflight);id('qbLaunch').onclick=e=>act(e.currentTarget,async()=>{if(!plan||plan.project_id!==S.project?.id)throw Error(tr('Create a plan for the active project first.'));await refreshPlanPreflight();if(!plan.preflight?.ready)throw Error(tr('Preflight is blocked. Fix the reported runtime requirements first.'));await req('/benchmarks/'+plan.id+'/launch','POST',{confirm:true});id('qbLaunch').hidden=true;await refreshReport();projectRecoveryUntil=Date.now()+120000;startPolling();});
id('qbRefresh').onclick=e=>act(e.currentTarget,async()=>{await refresh();if(typeof q22RefreshLatents==='function')await q22RefreshLatents();renderBenchmarkChoices();await history();await refreshReport();});
id('qbOpen').onclick=e=>act(e.currentTarget,async()=>{plan=null;report=null;await refreshReport();});
id('qbRetry').onclick=e=>act(e.currentTarget,async()=>{if(!report)return;if(!confirm(tr('Resume this batch? Completed jobs will be kept. Failed, interrupted or missing jobs will be re-queued, including combinations currently flagged as incompatible.')))return;const r=await req('/benchmarks/'+report.id+'/retry','POST',{});const forced=(r.forced_incompatible||[]).length;const skipped=(r.skipped_incompatible||[]).length;id('qbStatus').textContent=tr('Batch resumed')+' · '+r.count+' '+tr('Jobs queued')+(forced?' · '+forced+' '+tr('incompatible retried'):'')+(skipped?' · '+skipped+' '+tr('non-retryable skipped'):'');projectRecoveryUntil=Date.now()+120000;startPolling();await refreshReport();});
id('qbPauseUpdates').onclick=e=>{pollingPaused=!pollingPaused;e.currentTarget.textContent=tr(pollingPaused?'Resume updates':'Pause updates');id('qbStatus').textContent=tr(pollingPaused?'Live updates paused. Jobs continue on the server.':'Live updates resumed.');if(!pollingPaused)refreshReport(true).catch(err=>{id('qbStatus').textContent=err.message});};
id('qbCancel').onclick=e=>act(e.currentTarget,async()=>{if(report&&confirm(tr('Cancel queued and running tests in this comparison?'))){await req('/benchmarks/'+report.id+'/cancel','POST',{});await refreshReport();}});
window.addEventListener('qwen-hub-updated',()=>refresh().catch(e=>status(e.message,true)));window.addEventListener('qwen-comfy-runtime-updated',()=>{if(plan?.id)refreshPlanPreflight().catch(e=>{id('qbStatus').textContent=e.message})});
window.addEventListener('creator-view-change',e=>{if(['user-presets','benchmark'].includes(e.detail?.view))act(null,async()=>{await refresh();if(e.detail.view==='benchmark'){if(typeof q22RefreshLatents==='function')await q22RefreshLatents();renderBenchmarkChoices();await history();}});});
