window.QwenStudio={requestSetup:()=>{if(!loaded)throw Error(tr('Wait for the preset catalog to load.'));if(setup.model_preset_id==='@configured'&&!Object.keys(setup.overrides).length&&!Object.keys(setup.load_options).length&&!setup.use_profile_loras)return {};return JSON.parse(JSON.stringify(setup))},refresh,apply,prepare:makePlan,get state(){return {setup,data,plan,report}}};
refresh().catch(e=>status(e.message,true));
